/**
 * @file QuestDB.js
 * @brief Read-only repository of the quests (C++: class QuestDB : public DataRepository).
 * Built from data/raw/quests-data.js (generated by tools/data/gen-quests.mjs). Every entry is a
 * frozen QuestDefinition keyed by '<category>.<id>' ('main.12', 'side.leg_latias_2'):
 *   { key, category, id, region|null, location|null, objective { type, count, … },
 *     rewards { questPoints, items { id: qty }, pokemon|null }, chain|null, requires|null,
 *     encounter|null, locked|null }
 * Player state is NOT here (data/save/QuestProgressData.js). Texts:
 * t('quests.<category>.<id>.title') / t('quests.<category>.<id>.desc').
 */
import { DataRepository, deepFreeze } from '../core/DataRepository.js';
import { QUESTS_TABLE as GENERATED_QUESTS } from '../raw/quests-data.js';
import { QUESTS_CONTENT } from '../content/quests-content.js';
import { withContentList } from '../core/ContentTables.js';

const QUESTS_TABLE = withContentList(GENERATED_QUESTS, QUESTS_CONTENT, (quest) => `${quest.category}:${quest.id}`);
import { QuestCategories } from './QuestCategories.js';
import { ObjectiveRegistry } from './objectives/ObjectiveRegistry.js';
import { LocationDB } from '../world/LocationDB.js';
import { ItemDB } from '../items/ItemDB.js';
import { PokemonDB } from '../pokemon/PokemonDB.js';
import { REGIONS } from '../../config/Regions.js';
import { TrainerDB } from '../trainers/TrainerDB.js';
import { LeagueDB } from '../trainers/LeagueDB.js';
import { CURRENCIES } from '../save/CurrencyDefinitions.js';
import { QuestRules } from '../../config/QuestRules.js';

/** @param {*} value @returns {number} */
function positiveInteger(value) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(0, Math.floor(number)) : 0;
}

/** @param {Object} raw */
function readRewards(raw = {}) {
  const questPoints = positiveInteger(raw.questPoints);
  const currencies = {};
  for (const [currencyId, rawQuantity] of Object.entries(raw.currencies || {})) {
    const quantity = positiveInteger(rawQuantity);
    if (quantity > 0) currencies[currencyId] = quantity;
  }
  // Backward-compatible source data: questPoints has always paid the quest-point currency.
  if (questPoints > 0 && currencies[QuestRules.REWARD_CURRENCY] == null) {
    currencies[QuestRules.REWARD_CURRENCY] = questPoints;
  }
  const items = {};
  for (const [itemId, rawQuantity] of Object.entries(raw.items || {})) {
    const quantity = positiveInteger(rawQuantity);
    if (quantity > 0) items[itemId] = quantity;
  }
  return {
    questPoints,
    currencies,
    items,
    pokemon: raw.pokemon ? { ...raw.pokemon } : null
  };
}

export class QuestDB extends DataRepository {
  /** @type {QuestDB|null} */
  static _instance = null;

  /** @returns {QuestDB} */
  static getInstance() {
    if (!QuestDB._instance) QuestDB._instance = new QuestDB();
    return QuestDB._instance;
  }

  constructor() {
    super('QuestDB');
  }

  /**
   * @param {string} category
   * @param {string} id
   * @returns {string} QuestDB key
   */
  static keyOf(category, id) {
    return `${category}.${id}`;
  }

  /** @protected @override */
  _build() {
    /** @private @type {Map<string, Readonly<Object>[]>} region -> main chain */
    this._mainChains = new Map();
    for (const raw of QUESTS_TABLE) {
      const key = QuestDB.keyOf(raw.category, raw.id);
      const quest = deepFreeze({
        key,
        category: raw.category,
        id: String(raw.id),
        region: raw.region || null,
        location: raw.location || null,
        objective: { ...raw.objective, count: Math.max(1, Number(raw.objective?.count) || 1) },
        rewards: readRewards(raw.rewards),
        chain: raw.chain ? { ...raw.chain } : null,
        requires: raw.requires ? { ...raw.requires } : null,
        encounter: raw.encounter ? { ...raw.encounter } : null,
        locked: raw.locked || null
      });
      this._entries.set(key, quest);
      if (quest.category === QuestCategories.MAIN) {
        if (!this._mainChains.has(quest.region)) this._mainChains.set(quest.region, []);
        this._mainChains.get(quest.region).push(quest);
      }
    }
    for (const chain of this._mainChains.values()) Object.freeze(chain);
  }

  /**
   * @param {string} category - QuestCategories value
   * @returns {Readonly<Object>[]} In table order
   */
  getByCategory(category) {
    return this.getAll().filter((quest) => quest.category === category);
  }

  /**
   * @param {string} region
   * @returns {ReadonlyArray<Readonly<Object>>} Main quests of the region, in story order
   */
  getMainChain(region) {
    return this._mainChains.get(region) || [];
  }

  /**
   * @param {string} region
   * @param {number} step - Index in the main chain (QuestProgressData.getMainStep)
   * @returns {Readonly<Object>|null} null once the chain is finished
   */
  getMainQuest(region, step) {
    return this.getMainChain(region)[step] || null;
  }

  /**
   * @param {Readonly<Object>} quest - A chain step
   * @returns {Readonly<Object>|null} The previous step of its legendary chain
   */
  getPreviousChainStep(quest) {
    if (!quest?.chain || quest.chain.step <= 1) return null;
    return this.getById(QuestDB.keyOf(quest.category, `${quest.chain.id}_${quest.chain.step - 1}`));
  }

  /** @override */
  validate() {
    const problems = [];
    const regionIds = REGIONS.map((region) => region.id);
    const locations = LocationDB.getInstance();
    const items = ItemDB.getInstance();
    const species = PokemonDB.getInstance();
    const currencyIds = new Set(CURRENCIES.map((currency) => currency.id));
    for (const quest of this._entries.values()) {
      const { key, objective, rewards } = quest;
      if (!Object.values(QuestCategories).includes(quest.category)) problems.push(this._problem(key, 'category', quest.category));
      if (quest.region && !regionIds.includes(quest.region)) problems.push(this._problem(key, 'region', quest.region));
      if (quest.location && !locations.has(quest.location)) problems.push(this._problem(key, 'location', quest.location));
      if (!ObjectiveRegistry.has(objective.type)) problems.push(this._problem(key, 'objective.type', objective.type));
      if (objective.location && !locations.has(objective.location)) problems.push(this._problem(key, 'objective.location', objective.location));
      if (objective.item && !items.has(objective.item)) problems.push(this._problem(key, 'objective.item', objective.item));
      if (objective.trainer && !TrainerDB.getInstance().has(objective.trainer)) problems.push(this._problem(key, 'objective.trainer', objective.trainer));
      if (objective.badge && !TrainerDB.getInstance().has(objective.badge) && !LeagueDB.getInstance().has(objective.badge)) {
        problems.push(this._problem(key, 'objective.badge', objective.badge));
      }
      if (objective.species && !species.has(objective.species)) problems.push(this._problem(key, 'objective.species', objective.species));
      for (const itemId of Object.keys(rewards.items)) {
        if (!items.has(itemId)) problems.push(this._problem(key, 'rewards.items', itemId));
      }
      for (const currencyId of Object.keys(rewards.currencies || {})) {
        if (!currencyIds.has(currencyId)) problems.push(this._problem(key, 'rewards.currencies', currencyId));
      }
      if (rewards.pokemon && !species.has(rewards.pokemon.species)) problems.push(this._problem(key, 'rewards.pokemon', rewards.pokemon.species));
      if (quest.encounter && !locations.has(quest.encounter.location)) problems.push(this._problem(key, 'encounter', quest.encounter.location));
      for (const caught of quest.requires?.caught || []) {
        if (!species.has(caught)) problems.push(this._problem(key, 'requires.caught', caught));
      }
      if (quest.chain && quest.chain.step > 1 && !this.getPreviousChainStep(quest)) problems.push(this._problem(key, 'chain', quest.chain.id));
    }
    return problems;
  }
}
